/* @autogenerated */
import { CommonModule } from '@angular/common';
import { Component, effect, input, OnDestroy, OnInit } from '@angular/core';
import { FormControl, FormGroup, ReactiveFormsModule, Validators } from '@angular/forms';
import { MatFormFieldModule } from '@angular/material/form-field';
import { MatInputModule } from '@angular/material/input';
import { MatSelectModule } from '@angular/material/select';
import { TranslocoModule } from '@jsverse/transloco';
import { BaseEditable } from '../base-editable';
import { SubFormEditable } from '../subform-editable';

export interface Address {
  street: string | null;
  city: string | null;
  zip: string | null;
  province: string | null;
  country: string | null;
}

const ZIP_PATTERNS: Record<string, RegExp> = {
  ES: /^\d{5}$/,
  US: /^\d{5}(-\d{4})?$/,
  GB: /^[A-Z]{1,2}\d[A-Z\d]?\s?\d[A-Z]{2}$/i,
  DE: /^\d{5}$/,
  FR: /^\d{5}$/,
  IT: /^\d{5}$/,
  PT: /^\d{4}-\d{3}$/,
  CA: /^[A-Z]\d[A-Z]\s?\d[A-Z]\d$/i,
  AU: /^\d{4}$/,
  MX: /^\d{5}$/,
  BR: /^\d{5}-?\d{3}$/,
  AR: /^[A-Z]?\d{4}[A-Z]{0,3}$/i,
  NL: /^\d{4}\s?[A-Z]{2}$/i,
  BE: /^\d{4}$/,
  CH: /^\d{4}$/,
  AT: /^\d{4}$/,
  PL: /^\d{2}-\d{3}$/,
  JP: /^\d{3}-?\d{4}$/,
  CN: /^\d{6}$/,
  IN: /^\d{6}$/,
  RU: /^\d{6}$/,
};

export const COMMON_COUNTRIES: { code: string; name: string }[] = [
  { code: 'ES', name: 'España' },
  { code: 'US', name: 'United States' },
  { code: 'GB', name: 'United Kingdom' },
  { code: 'DE', name: 'Deutschland' },
  { code: 'FR', name: 'France' },
  { code: 'IT', name: 'Italia' },
  { code: 'PT', name: 'Portugal' },
  { code: 'MX', name: 'México' },
  { code: 'AR', name: 'Argentina' },
  { code: 'CO', name: 'Colombia' },
  { code: 'CL', name: 'Chile' },
  { code: 'BR', name: 'Brasil' },
  { code: 'AU', name: 'Australia' },
  { code: 'CA', name: 'Canada' },
  { code: 'CH', name: 'Schweiz' },
  { code: 'NL', name: 'Nederland' },
  { code: 'BE', name: 'Belgique' },
  { code: 'AT', name: 'Österreich' },
  { code: 'PL', name: 'Polska' },
  { code: 'JP', name: 'Japan' },
];

@Component({
  selector: 'editable-address',
  standalone: true,
  imports: [CommonModule, ReactiveFormsModule, MatFormFieldModule, MatInputModule, MatSelectModule, TranslocoModule],
  providers: BaseEditable.getValidableAccessorProvider(EditableAddressComponent),
  templateUrl: './editable-address.component.html',
  styleUrls: ['./editable-address.component.scss'],
})
export class EditableAddressComponent extends SubFormEditable<Address> implements OnInit, OnDestroy {
  showProvince = input<boolean>(true);
  countryOptions = input<{ code: string; name: string }[]>(COMMON_COUNTRIES);
  zipPatternOverride = input<Record<string, RegExp>>({});

  constructor() {
    super(
      new FormGroup({
        street: new FormControl<string | null>(null, Validators.required),
        city: new FormControl<string | null>(null, Validators.required),
        zip: new FormControl<string | null>(null),
        province: new FormControl<string | null>(null),
        country: new FormControl<string | null>(null),
      }),
    );

    this.defaultValues = () => ({ street: null, city: null, zip: null, province: null, country: null });

    effect(() => {
      const country = this.form.get('country')?.value as string | null;
      this.updateZipValidator(country);
    });
  }

  private updateZipValidator(country: string | null): void {
    const zipCtrl = this.form.get('zip');
    if (!zipCtrl) return;

    const patterns = { ...ZIP_PATTERNS, ...this.zipPatternOverride() };
    const pattern = country ? patterns[country] : null;

    const validators = pattern ? [Validators.pattern(pattern)] : [];
    zipCtrl.setValidators(validators);
    zipCtrl.updateValueAndValidity({ emitEvent: false });
  }
}
